SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 9.3.1.1 RAD2 (E2)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD2 The height of tall structures (e.g. antenna, aerial, chimney, flagpole or the like) projects no more than 8.5m above ground level and transmission and receiving dishes are no larger than 1.2m diameter.$q$, 'VERIFIED_VERBATIM', $q$rule 19682$q$, NULL, $q$9.3.1 Dwelling house code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/226/0/false/11-Sep-2026/false$q$, $q$$q$, $q$mb_dh_rad2_tall_structures$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_dh_rad2_tall_structures", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "HEIGHT.BUILDING", "title": "Table 9.3.1.1 RAD2 (E2)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_HEIGHT", "operator": "<=", "value": 8.5, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/COASTAL_COMMUNITIES"}, {"level": "LOCAL_PLAN_PRECINCT", "local_plan_precinct": "CMB:REDCLIFFE_KIPPA_RING/INTERIM_RESIDENTIAL"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/SUBURBAN_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/NEXT_GENERATION_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:EMERGING_COMMUNITY/TRANSITION_DEVELOPED_LOT"}, {"level": "LOCAL_PLAN_PRECINCT", "local_plan_precinct": "CMB:CABOOLTURE_WEST/URBAN_LIVING_NEXT_GENERATION"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/URBAN_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:EMERGING_COMMUNITY/TRANSITION_DEVELOPED_LOT_MORAYFIELD_SOUTH"}], "subjects": ["ANY"], "sources": [{"key": "mb_dh_rad2_tall_structures", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"tall_structure_height_above_ground\", \"operator\": \"<=\", \"value\": 8.5, \"unit\": \"m\", \"conditions\": [\"dishes <= 1.2 m diameter\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'Tall structures (antenna, aerial, chimney, flagpole), dishes' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: YES - RAD carries note 'Non-compliance with this RAD is a planning scheme matter for which Council will exercise a concurrence agency role ...'; Table 1.6.1 identifies 9.3.1 'RADs and performance outcomes identified by notes as a planning scheme matter' as the alternative provisions to QDC boundary clearance and site cover provisions (Building Act s33)."}$q$::jsonb);
