SELECT define_rule($q${"rule_id": "CMB.mb_dh_t93115_nextgen_side", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "SETBACK.SIDE", "title": "Table 9.3.1.5 Setbacks (via RAD3/E3.1)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "TABLE", "measurement": "SCHEME_SETBACK_SIDE", "operator": ">=", "value": {"op": "unencoded", "text": "Side to wall: frontage <= 12 m (wall < 4.5 m) -> 1 m; otherwise QDC standard measured to wall. Side/rear to OMP = applicable side or rear standard to wall minus 0.5 m.", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/NEXT_GENERATION_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:EMERGING_COMMUNITY/TRANSITION_DEVELOPED_LOT"}, {"level": "LOCAL_PLAN_PRECINCT", "local_plan_precinct": "CMB:CABOOLTURE_WEST/URBAN_LIVING_NEXT_GENERATION"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mb_dh_t93115_nextgen_side", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_side_setback\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"wall < 4.5 m: For lots with a primary frontage ≤12m, Min 1m OR For lots with a primary frontage >12m, refer to standard as in QDC but measured to wall\", \"wall 4.5-8.5 m: Refer to standard as in QDC but measured to wall\", \"wall > 8.5 m: Refer to standard as in QDC but measured to wall\"], \"exceptions\": [\"built to boundary walls per RAD4/Table 9.3.1.7\"], \"formula_text\": \"Side to wall: frontage <= 12 m (wall < 4.5 m) -> 1 m; otherwise QDC standard measured to wall. Side/rear to OMP = applicable side or rear standard to wall minus 0.5 m.\"}\nStructure scope 'Class 1a and Class 10a (non-built-to-boundary walls)' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES - RAD carries note 'Non-compliance with this RAD is a planning scheme matter for which Council will exercise a concurrence agency role ...'; Table 1.6.1 identifies 9.3.1 'RADs and performance outcomes identified by notes as a planning scheme matter' as the alternative provisions to QDC boundary clearance and site cover provisions (Building Act s33).\nResearcher notes: Where the cell says 'Refer to standard as in QDC', the numeric value comes from the QDC (now QHC) - the scheme does not itself state a number."}$q$::jsonb);
