SELECT define_rule($q${"rule_id": "CMB.mb_dh_t93115_nextgen_rear", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "SETBACK.REAR", "title": "Table 9.3.1.5 Setbacks (via RAD3/E3.1)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "TABLE", "measurement": "SCHEME_SETBACK_REAR", "operator": ">=", "value": {"op": "unencoded", "text": "Rear to wall: 5 m; 3 m if longest side boundary <= 25 m or primary frontage <= 9.5 m; QDC standard measured to wall if frontage <= 9.5 m and lot adjoins/is opposite a park. Rear to OMP = rear standard to wall minus 0.5 m.", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/NEXT_GENERATION_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:EMERGING_COMMUNITY/TRANSITION_DEVELOPED_LOT"}, {"level": "LOCAL_PLAN_PRECINCT", "local_plan_precinct": "CMB:CABOOLTURE_WEST/URBAN_LIVING_NEXT_GENERATION"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mb_dh_t93115_nextgen_rear", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_rear_setback\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"wall < 4.5 m: Min 5m OR Where the longest side boundary is ≤25m or where the primary frontage is ≤9.5m - Min 3m OR Where the primary frontage is ≤9.5m and the lot is adjoining a park or directly opposite a park fronting the same street - refer to standard as in QDC but measured to wall\", \"wall 4.5-8.5 m: Min 5m OR Where the longest side boundary is ≤25m or where the primary frontage is ≤9.5m - Min 3m OR Where the primary frontage is ≤9.5m and the lot is adjoining a park or directly opposite 