SELECT define_rule($q${"rule_id": "CMB.mb_dh_t93116_urban_waterbody", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "OTHER", "title": "Table 9.3.1.6 Setbacks (via RAD3/E3.1)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "TABLE", "measurement": "SCHEME_OTHER", "operator": ">=", "value": 4.5, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/URBAN_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:EMERGING_COMMUNITY/TRANSITION_DEVELOPED_LOT_MORAYFIELD_SOUTH"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mb_dh_t93116_urban_waterbody", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_trafficable_water_body_setback\", \"operator\": \">=\", \"value\": 4.5, \"unit\": \"m\", \"conditions\": [\"applies to OMP, wall and covered car parking/domestic outbuildings, all wall heights\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'Class 1a and Class 10a incl. covered car parking and domestic outbuildings' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES - RAD carries note 'Non-compliance with this RAD is a planning scheme matter for which Council will exercise a concurrence agency role ...'; Table 1.6.1 identifies 9.3.1 'RADs and performance outcomes identified by notes as a planning scheme matter' as the alternative provisions to QDC boundary clearance and site cover provisions (Building Act s33)."}$q$::jsonb);
