SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 9.3.1.1 RAD4 (E3.2)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD4 Built to boundary walls are: - provided on lots if required by an existing approval issued by Council, and are established in accordance with the plan of development under that existing approval (including any subsequent amendments to that plan of development that are approved by council in writing) OR if no approved plan of development applies to the land, are only established on lots having a primary frontage of 18m or less and where permitted in Table 9.3.1.7 'Built to boundary walls'; - of a length and height not exceeding that specified in Table 9.3.1.7 'Built to boundary walls'; - setback from the side boundary: - if a plan of development provides for only one built to boundary wall on the one boundary, not more than 200mm; or - if a built to boundary wall may be built on each side of the same boundary, not more than 20mm; - on the low side of a sloping lot. ... Note - The above setbacks apply only to Class 1a and Class 10a buildings/structures. Note - Non-compliance with this RAD is a planning scheme matter ...$q$, 'VERIFIED_VERBATIM', $q$rule 19685$q$, NULL, $q$9.3.1 Dwelling house code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/226/0/false/11-Sep-2026/false$q$, $q$Built to boundary wall = 'A wall of a Dwelling house (class 1a) setback 200mm or less from a boundary.'$q$, $q$mb_dh_rad4_btb_general$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_dh_rad4_btb_general", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "SETBACK.SIDE_REAR.BTB", "title": "Table 9.3.1.1 RAD4 (E3.2)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_BTB_LENGTH", "operator": "<=", "value": {"op": "unencoded", "text": "RAD4 Built to boundary walls are: - provided on lots if required by an existing approval issued by Council, and are established in accordance with the plan of development under that existing approval (including any subsequent amendments to that plan of development that are approved by council in writing) OR if no approved plan of development applies to the land, are only established on lots having a primary frontage of 18m or less and where permitted in Table 9.3.1.7 'Built to boundary walls'; - of a length and height not exceeding that specified in Table 9.3.1.7 'Built to boundary walls'; - setback from the side boundary: - if a plan of development provides for only one built to boundary wall on the one boundary, not more than 200mm; or - if a built to boundary wall may be built on each side of the same boundary, not more than 20mm; - on the low side of a sloping lot. ... Note - The above setbacks apply only to Class 1a and Class 10a buildings/structures. Note - Non-compliance with this RAD is a planning scheme matter ...", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/COASTAL_COMMUNITIES"}, {"level": "LOCAL_PLAN_PRECINCT", "local_plan_precinct": "CMB:REDCLIFFE_KIPPA_RING/INTERIM_RESIDENTIAL"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/SUBURBAN_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/NEXT_GENERATION_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:EMERGING_COMMUNITY/TRANSITION_DEVELOPED_LOT"}, {"level": "LOCAL_PLAN_PRECINCT", "local_plan_precinct": "CMB:CABOOLTURE_WEST/URBAN_LIVING_NEXT_GENERATION"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/URBAN_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:EMERGING_COMMUNITY/TRANSITION_DEVELOPED_LOT_MORAYFIELD_SOUTH"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mb_dh_rad4_btb_general", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"btb_permitted\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"no plan of development: primary frontage <= 18 m and permitted by Table 9.3.1.7\", \"BTB wall within 200 mm of boundary (one wall) or 20 mm (walls both sides)\", \"on the low side of a sloping lot\"], \"exceptions\": [\"approved plan of development governs where one exists\"], \"formula_text\": null}\nStructure scope 'Class 1a and Class 10a buildings/structures' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES - RAD carries note 'Non-compliance with this RAD is a planning scheme matter for which Council will exercise a concurrence agency role ...'; Table 1.6.1 identifies 9.3.1 'RADs and performance outcomes identified by notes as a planning scheme matter' as the alternative provisions to QDC boundary clearance and site cover provisions (Building Act s33)."}$q$::jsonb);
