SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 9.3.1.7 (via RAD4)$q$, 'TABLE', $q$Table 9.3.1.7 Built to boundary walls. Columns: Lot frontage widths || Mandatory / Optional || [GRZ Coastal communities, Suburban neighbourhood; Redcliffe Interim residential] || [Emerging community Transition (developed lot); GRZ Next generation; Caboolture West Next generation sub-precinct] || [Emerging community Transition (developed lot) in Morayfield South; GRZ Urban neighbourhood]. 7.5m or less || Mandatory - both sides unless a corner lot || Not permitted* || Max length: 80% of the length of the boundary Max Height: 7.5m || Max Length: 80% of the length of the boundary Max Height: 8.5m ; More than 7.5m to 9.5m || Mandatory - one side Optional to both sides in the following locations only unless a corner lot: [Transition, Next generation, Caboolture West Next generation] || Not permitted* || Max Length: 60% of the length of the boundary OR 80% if the lot adjoining that boundary has a frontage of 9.5m or less. Max Height:7.5m || Max Length: 70% of the length of the boundary Max Height: 10.5m ; More than 9.5m to 12.5m || Mandatory - one side || Not permitted* || Max Length: 60% of the length of the boundary OR 80% if the lot adjoining that boundary has a frontage of 7.5m or less. Max Height 7.5m || Max Length: 70% of the length of the boundary Max Height: 10.5m ; More than 12.5m to 18m || Optional: - on 1 boundary only; - where the built to boundary wall adjoins a lot with a frontage less than 18m. Not permitted - Otherwise || Not permitted* || Max Length: the lesser of 15m or 60% of the length of the boundary Max Height: 7.5m || Max Length: the lesser of 15m or 60% of the length of the boundary Max Height: 10.5m ; Greater than 18m || Not permitted* || Not permitted* || Not Permitted* || Not Permitted*. Note - The above setbacks apply only to Class 1a and Class 10a buildings/structures. Note - Max length includes the length of walls of any other buildings on the same boundary. e.g detached garage, carport or shed. Note - For the maximum height of domestic outbuildings refer to the examples that achieve aspects of the performance outcomes for building height and domestic outbuildings. *Note - Built to boundary walls are not permitted, however, reduced side and rear boundary clearances may be permitted as prescribed (e.g QDC).$q$, 'VERIFIED_VERBATIM', $q$rules 30043-30052$q$, NULL, $q$9.3.1 Dwelling house code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/226/0/false/11-Sep-2026/false$q$, $q$$q$, $q$mb_dh_t93117_btb_coastal_suburban$q$);
