SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 9.3.1.1 RAD5 (E4)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD5 Site cover (excluding eaves, sun shading devices, patios, balconies and other unenclosed structures) does not exceed: - Emerging community zone: - Transition precinct (developed lot) - in accordance with Table 9.3.1.8 - General residential zone: - Coastal communities precinct – 50% - Suburban neighbourhood precinct – 50% - Next generation neighbourhood precinct – in accordance with Table 9.3.1.8 - Urban neighbourhood precinct – in accordance with Table 9.3.1.9 - Caboolture West local plan: - Urban living precinct - Next generation sub-precinct - in accordance with Table 9.3.1.8 - Redcliffe Kippa-Ring local plan: - Interim residential precinct - 50% Note - Non-compliance with this RAD is a planning scheme matter ...$q$, 'VERIFIED_VERBATIM', $q$rule 19687$q$, NULL, $q$9.3.1 Dwelling house code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/226/0/false/11-Sep-2026/false$q$, $q$Site cover per Schedule 1 definition, calculated to outermost projections; RAD5 additionally excludes patios, balconies and other unenclosed structures (so open carports/patios/pergolas are excluded, though the definition itself includes carports).$q$, $q$mb_dh_rad5_site_cover_50$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_dh_rad5_site_cover_50", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "SITE_COVER", "title": "Table 9.3.1.1 RAD5 (E4)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SITE_COVER", "operator": "<=", "value": 50, "unit": "%", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/COASTAL_COMMUNITIES"}, {"level": "LOCAL_PLAN_PRECINCT", "local_plan_precinct": "CMB:REDCLIFFE_KIPPA_RING/INTERIM_RESIDENTIAL"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/SUBURBAN_NEIGHBOURHOOD"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mb_dh_rad5_site_cover_50", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"max_site_cover\", \"operator\": \"<=\", \"value\": 50, \"unit\": \"%\", \"conditions\": [\"any lot size\"], \"exceptions\": [\"excludes eaves, sun shading devices, patios, balconies and other unenclosed structures\"], \"formula_text\": null}\nStructure scope 'Dwelling house incl. enclosed Class 10a' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES - RAD carries note 'Non-compliance with this RAD is a planning scheme matter for which Council will exercise a concurrence agency role ...'; Table 1.6.1 identifies 9.3.1 'RADs and performance outcomes identified by notes as a planning scheme matter' as the alternative provisions to QDC boundary clearance and site cover provisions (Building Act s33).\nResearcher notes: Conflict to resolve: the 'site cover' definition includes carport(s), but RAD5 excludes 'other unenclosed structures'."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_dh_rad5_site_cover_50@2026-09-11$q$;
