SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 9.3.1.8 Site cover (via RAD5/E4)$q$, 'TABLE', $q$Table 9.3.1.8 Site cover - Emerging community zone - Transition precinct (developed lot), General residential zone - Next generation neighbourhood precinct and Caboolture West local plan - Urban living precinct - Next generation sub-precinct. Building height || Lot Size: 300m2 or less [terrace: Primary frontage width is less than 7.5m; built to boundary walls are provided to both side boundaries | terrace: Primary frontage width is 7.5m to 9.5m; built to boundary walls are provided to both side boundaries | traditional: Any built to boundary walls are limited to one side boundary only] || 301-400m2 || 401-500m2 || 501-1000m2 || Greater than 1000m2. 8.5m or less || 80% || 75% || 60% || 60% || 60% || 60% || 60% ; >8.5m - 12.0m || 50% || 50% || 50% || 50% || 60% || 50% || 50% ; >12.0m || N/A || N/A || N/A || N/A || N/A || 50% || 40%$q$, 'VERIFIED_VERBATIM', $q$rules 32381, 30096, 30056-30058$q$, NULL, $q$9.3.1 Dwelling house code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/226/0/false/11-Sep-2026/false$q$, $q$$q$, $q$mb_dh_t93118_site_cover_nextgen$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_dh_t93118_site_cover_nextgen", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "SITE_COVER", "title": "Table 9.3.1.8 Site cover (via RAD5/E4)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "TABLE", "measurement": "SCHEME_SITE_COVER", "operator": "<=", "value": {"op": "unencoded", "text": "Table 9.3.1.8 Site cover - Emerging community zone - Transition precinct (developed lot), General residential zone - Next generation neighbourhood precinct and Caboolture West local plan - Urban living precinct - Next generation sub-precinct. Building height || Lot Size: 300m2 or less [terrace: Primary frontage width is less than 7.5m; built to boundary walls are provided to both side boundaries | terrace: Primary frontage width is 7.5m to 9.5m; built to boundary walls are provided to both side boundaries | traditional: Any built to boundary walls are limited to one side boundary only] || 301-400m2 || 401-500m2 || 501-1000m2 || Greater than 1000m2. 8.5m or less || 80% || 75% || 60% || 60% || 60% || 60% || 60% ; >8.5m - 12.0m || 50% || 50% || 50% || 50% || 60% || 50% || 50% ; >12.0m || N/A || N/A || N/A || N/A || N/A || 50% || 40%", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "%", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/NEXT_GENERATION_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:EMERGING_COMMUNITY/TRANSITION_DEVELOPED_LOT"}, {"level": "LOCAL_PLAN_PRECINCT", "local_plan_precinct": "CMB:CABOOLTURE_WEST/URBAN_LIVING_NEXT_GENERATION"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mb_dh_t93118_site_cover_nextgen", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"max_site_cover\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"%\", \"conditions\": [\"height <= 8.5 m: <=300 m2 terrace (<7.5 m frontage, BTB both sides) 80%; <=300 m2 terrace (7.5-9.5 m) 75%; <=300 m2 traditional 60%; 301-400 60%; 401-500 60%; 501-1000 60%; >1000 60%\", \"height > 8.5-12 m: 50/50/50/50/60/50/50 (sic - 60% in 401-500 m2 column)\", \"height > 12 m: N/A except 501-1000 m2 50%, >1000 m2 40%\"], \"exceptions\": [\"excludes eaves, sun shading devices, patios, balconies and other unenclosed structures (RAD5)\"], \"formula_text\": null}\nStructure scope 'Dwelling house incl. enclosed Class 10a' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES - RAD carries note 'Non-compliance with this RAD is a planning scheme matter for which Council will exercise a concurrence agency role ...'; Table 1.6.1 identifies 9.3.1 'RADs and performance outcomes identified by notes as a planning scheme matter' as the alternative provisions to QDC boundary clearance and site cover provisions (Building Act s33).\nResearcher notes: Column mapping verified from raw HTML colspans (300 m2 or less spans 3 sub-columns). The 60% in the >8.5-12 m / 401-500 m2 cell is as published."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_dh_t93118_site_cover_nextgen@2026-09-11$q$;
