SELECT define_rule($q${"rule_id": "CMB.mb_dh_t93119_site_cover_urban", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "SITE_COVER", "title": "Table 9.3.1.9 Site cover (via RAD5/E4)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "TABLE", "measurement": "SCHEME_SITE_COVER", "operator": "<=", "value": {"op": "unencoded", "text": "Table 9.3.1.9 Site cover - General residential zone - Urban neighourhood precinct. Building height || Lot Size: 300m2 or less || 301-400m2 || 401-500m2 || 501-1000m2 || Greater than 1000m2. 8.5m or less || 75% || 70% || 60% || 60% || 60% ; >8.5m - 12.0m || 50% || 50% || 60% || 50% || 50% ; >12.0m || N/A || N/A || N/A || 50% || 40%", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "%", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/URBAN_NEIGHBOURHOOD"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mb_dh_t93119_site_cover_urban", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"max_site_cover\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"%\", \"conditions\": [\"height <= 8.5 m: 75/70/60/60/60\", \"> 8.5-12 m: 50/50/60/50/50\", \"> 12 m: N/A/N/A/N/A/50/40\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'Dwelling house incl. enclosed Class 10a' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES - RAD carries note 'Non-compliance with this RAD is a planning scheme matter for which Council will exercise a concurrence agency role ...'; Table 1.6.1 identifies 9.3.1 'RADs and performance outcomes identified by notes as a planning scheme matter' as the alternative provisions to QDC boundary clearance and site cover provisions (Building Act s33)."}$q$::jsonb);
