SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$7.2.1.6 Table 7.2.1.6.3 Setbacks (via RAD3, Part K)$q$, 'TABLE', $q$Table 7.2.1.6.3 Setbacks - Residential uses. Height of wall || Frontage Primary [To wall | To OMP | To car parking space] || Frontage Secondary to Street [To wall | To OMP | To car parking space] || Frontage Secondary to lane || Side To OMP and wall || Rear To OMP and wall. Less than 4.5m || Min 6m || Min 4.5m || Min 5.4m || Min 3m || Min 2m || Min 5.4m || Min 0.5m || Min 1.5m || Min 1.5m ; 4.5m to 8.5m || Min 6m || Min 4.5m || N/A || Min 3m || Min 2m || N/A || Min 0.5m || Min 2m || Min 2m ; Greater than 8.5m || Min 6m || Min 4.5m || N/A || Min 3m || Min 2m || N/A || Min 0.5m || Min 2m up to 8.5m in height; plus 0.5m for every 3m in height (or storey) or part thereof over 8.5m || Min 2m up to 8.5m in height; plus 0.5m for every 3m in height (or storey) or part thereof over 8.5m$q$, 'VERIFIED_VERBATIM', $q$rule 24823-24825$q$, NULL, $q$7.2.1 Redcliffe Kippa-Ring local plan code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/189/0/false/11-Sep-2026/false$q$, $q$$q$, $q$mb_rkr_interim_setbacks_table_72163$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_rkr_interim_setbacks_table_72163", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "SETBACK.SIDE", "title": "7.2.1.6 Table 7.2.1.6.3 Setbacks (via RAD3, Part K)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "TABLE", "measurement": "SCHEME_SETBACK_SIDE", "operator": ">=", "value": {"op": "unencoded", "text": "h>8.5: 2 + 0.5*ceil((h-8.5)/3)", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "LOCAL_PLAN_PRECINCT", "local_plan_precinct": "CMB:REDCLIFFE_KIPPA_RING/INTERIM_RESIDENTIAL"}], "subjects": ["ANY"], "sources": [{"key": "mb_rkr_interim_setbacks_table_72163", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_side_rear_setback\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"wall < 4.5 m: side/rear 1.5 m\", \"4.5-8.5 m: 2 m\", \"> 8.5 m: 2 m + 0.5 m per 3 m (or storey) or part over 8.5 m\"], \"exceptions\": [], \"formula_text\": \"h>8.5: 2 + 0.5*ceil((h-8.5)/3)\"}\nLocal plan: Redcliffe Kippa-Ring local plan - Interim residential precinct\nStructure scope 'Residential uses' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: UNKNOWN\nResearcher notes: Part K (RADs for the Interim residential precinct) of the local plan code; Table 5.9.1.9 lists both 9.3.1 and 7.2.1 for dwelling-house building work there, and 1.5 says local plan codes prevail over use codes. But 9.3.1 RAD3 sends the same precinct to Table 9.3.1.3 (side/rear 'Refer to standard as in QDC'). Which table governs a dwelling house, and whether 7.2.1 is an alternative provision (it is not listed in Table 1.6.1), needs manual review. Local plan RAD1 also sets domestic outbuildings (incl. free standing carports and garages) to 4m and mean height 3.5m."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_rkr_interim_setbacks_table_72163@2026-09-11$q$;
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.10.1 RAD2 (Part B PO3/E3, PO52/E52)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD2 || Unless otherwise specified elsewhere in this code, building height and all structures do not exceed the height identified on Overlay map - Building heights; except in the Hamlet precinct, where outbuildings, free standing car ports or garages do not exceed 3.5m. Note - This is an alternative provision to the QDC for building work associated with a Dwelling house, and is a concurrence agency issue. Note - This provision does not apply to telecommunication facilities.$q$, 'VERIFIED_VERBATIM', $q$rule 13993$q$, NULL, $q$6.2.10 Rural zone code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/112/0/false/11-Sep-2026/false$q$, $q$Building height = vertical distance between ground level and the highest point of the building roof (apex) or parapet (Schedule 1). Mean height is not defined in the scheme (9.3.1 says it is defined in the QDC).$q$, $q$mb_rural_rad2_height_dwelling$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_rural_rad2_height_dwelling", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "HEIGHT.BUILDING", "title": "Table 6.2.10.1 RAD2 (Part B PO3/E3, PO52/E52)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_HEIGHT", "operator": "<=", "value": {"op": "unencoded", "text": "RAD2 || Unless otherwise specified elsewhere in this code, building height and all structures do not exceed the height identified on Overlay map - Building heights; except in the Hamlet precinct, where outbuildings, free standing car ports or garages do not exceed 3.5m. Note - This is an alternative provision to the QDC for building work associated with a Dwelling house, and is a concurrence agency issue. Note - This provision does not apply to telecommunication facilities.", "extracted_value": null, "extracted_operator": "<="}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "ZONE", "zone": "CMB:RURAL"}, {"level": "PRECINCT", "precinct": "CMB:RURAL/AGRICULTURE"}, {"level": "PRECINCT", "precinct": "CMB:RURAL/HAMLET"}, {"level": "PRECINCT", "precinct": "CMB:RURAL/RURAL_LIVING_INVESTIGATION"}, {"level": "PRECINCT", "precinct": "CMB:RURAL/WOODFORDIA_ABBEY"}, {"level": "PRECINCT", "precinct": "CMB:RURAL/CEDARTON_MT_NEBO"}], "subjects": ["ANY"], "sources": [{"key": "mb_rural_rad2_height_dwelling", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"max_building_height\", \"operator\": \"<=\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"value = maximum mapped on Overlay map - Building heights for the lot (open data suggests Max 8.5m across the Rural zone)\"], \"exceptions\": [\"Hamlet precinct: outbuildings, free standing car ports or garages max 3.5m (separate record)\", \"telecommunication facilities\"], \"formula_text\": null}\nStructure scope 'Dwelling house and all buildings/structures (incl. domestic outbuildings outside the Hamlet precinct)' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: YES - listed under 'Alternative provisions to the QDC' in the 6.2.10 'Concurrence agency issues for building work' table (RAD2, RAD8, RAD39; amenity and aesthetics column 'Nil'), and the RAD carries 'Note - This is an alternative provision to the QDC for building work associated with a Dwelling house, and is a concurrence agency issue.' Table 1.6.1 (rule 245) lists s6.2.10 as containing alternative provisions to QDC boundary clearance and site cover provisions.\nResearcher notes: Mapped value from Overlay map - Building heights. Spot check of council open-data layer OM_Building_Heights_WebMercator_OpenData (2022 data, not the legal V8 map) at 40 random parcel centroids per area: Township residential 40/40 'Max 8.5m'; Rural (no precinct) 38/40 'Max 8.5m' and 2 outside any polygon; Hamlet 40/40 'Max 8.5m'; Agriculture 40/40 'Max 8.5m'. Check each lot. Outside the Hamlet precinct the code sets no separate outbuilding height, so the mapped height applies to domestic outbuildings too ('building height and all structures')."}$q$::jsonb);
