SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.10.1 RAD3$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD3 || Unless otherwise specified elsewhere in the zone code and where not located in a bushfire prone area, the minimum setbacks from a lot boundary for buildings and structures other than a dwelling house, are as follows: - road boundary - 6m - side boundary - 4.5m - rear boundary - 4.5m. Note - Where located in a bushfire hazard area (see Overlay map - Bushfire hazard) a greater setback may be required. See values and constraints requirements Bushfire hazard. Note - This provision does not apply where a development footprint exists for a lot.$q$, 'VERIFIED_VERBATIM', $q$rule 13995$q$, NULL, $q$6.2.10 Rural zone code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/112/0/false/11-Sep-2026/false$q$, $q$Setback = 'shortest distance measured horizontally from the outer most projection of a building or structure to the vertical projection of the boundary of the lot' (Schedule 1).$q$, $q$mb_rural_rad3_road_setback_non_dwelling$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_rural_rad3_road_setback_non_dwelling", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "SETBACK.FRONTAGE", "title": "Table 6.2.10.1 RAD3", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": 6, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "ZONE", "zone": "CMB:RURAL"}], "subjects": ["ANY"], "sources": [{"key": "mb_rural_rad3_road_setback_non_dwelling", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_road_boundary_setback\", \"operator\": \">=\", \"value\": 6, \"unit\": \"m\", \"conditions\": [\"not located in a bushfire prone area\", \"unless otherwise specified elsewhere in the zone code\"], \"exceptions\": [\"dwelling house (expressly excluded)\", \"lot with a development footprint\", \"Hamlet precinct lots: RAD4 (more specific)\", \"bushfire hazard area: a greater setback may be required\"], \"formula_text\": null}\nStructure scope 'Buildings and structures other than a dwelling house (whether this covers domestic outbuildings is unclear)' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: NO - not listed in the 6.2.10 concurrence agency issues table (only RAD2, RAD8, RAD39 are) and carries no alternative-provision note; non-compliance makes the building work assessable (limited code assessment, s5.3.3.1.a.ii) against the corresponding PO.\nResearcher notes: RAD3 expressly excludes 'a dwelling house'. The Schedule 1 definition of Dwelling house includes 'any domestic outbuildings associated with the dwelling', so it is unclear whether RAD3 applies to a domestic shed/garage/carport. Outside the Hamlet precinct the Rural zone code has NO accepted-development boundary setback for the dwelling house itself (boundary clearance then falls to the QDC/QHC). The Part B example E4.1 (assessable development) gives 6m / 4.5m / 4.5m without the dwelling-house exclusion. 'Bushfire prone area' is not mapped by that name (the overlay is 'Bushfire hazard')."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_rural_rad3_road_setback_non_dwelling@2026-09-11$q$;
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.10.1 RAD3$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD3 || Unless otherwise specified elsewhere in the zone code and where not located in a bushfire prone area, the minimum setbacks from a lot boundary for buildings and structures other than a dwelling house, are as follows: - road boundary - 6m - side boundary - 4.5m - rear boundary - 4.5m. Note - Where located in a bushfire hazard area (see Overlay map - Bushfire hazard) a greater setback may be required. See values and constraints requirements Bushfire hazard. Note - This provision does not apply where a development footprint exists for a lot.$q$, 'VERIFIED_VERBATIM', $q$rule 13995$q$, NULL, $q$6.2.10 Rural zone code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/112/0/false/11-Sep-2026/false$q$, $q$Setback = 'shortest distance measured horizontally from the outer most projection of a building or structure to the vertical projection of the boundary of the lot' (Schedule 1).$q$, $q$mb_rural_rad3_side_setback_non_dwelling$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_rural_rad3_side_setback_non_dwelling", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "SETBACK.SIDE", "title": "Table 6.2.10.1 RAD3", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SETBACK_SIDE", "operator": ">=", "value": 4.5, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "ZONE", "zone": "CMB:RURAL"}], "subjects": ["ANY"], "sources": [{"key": "mb_rural_rad3_side_setback_non_dwelling", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_side_boundary_setback\", \"operator\": \">=\", \"value\": 4.5, \"unit\": \"m\", \"conditions\": [\"not located in a bushfire prone area\", \"unless otherwise specified elsewhere in the zone code\"], \"exceptions\": [\"dwelling house (expressly excluded)\", \"lot with a development footprint\", \"Hamlet precinct lots: RAD4 (more specific)\", \"bushfire hazard area: a greater setback may be required\"], \"formula_text\": null}\nStructure scope 'Buildings and structures other than a dwelling house (whether this covers domestic outbuildings is unclear)' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: NO - not listed in the 6.2.10 concurrence agency issues table (only RAD2, RAD8, RAD39 are) and carries no alternative-provision note; non-compliance makes the building work assessable (limited code assessment, s5.3.3.1.a.ii) against the corresponding PO.\nResearcher notes: RAD3 expressly excludes 'a dwelling house'. The Schedule 1 definition of Dwelling house includes 'any domestic outbuildings associated with the dwelling', so it is unclear whether RAD3 applies to a domestic shed/garage/carport. Outside the Hamlet precinct the Rural zone code has NO accepted-development boundary setback for the dwelling house itself (boundary clearance then falls to the QDC/QHC). The Part B example E4.1 (assessable development) gives 6m / 4.5m / 4.5m without the dwelling-house exclusion. 'Bushfire prone area' is not mapped by that name (the overlay is 'Bushfire hazard')."}$q$::jsonb);
