SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.10.2 PO4 / E4.1 / E4.2$q$, 'PERFORMANCE_OUTCOME', $q$PO4 Setbacks are: - sufficient to minimise overlooking and maintain privacy of adjoining properties; and - sufficient to ensure development is not visually dominant or overbearing on adjoining properties. || E4.1 Unless specified elsewhere in the zone code, the minimum setback from a boundary is as follows: - road boundary – 6m - side boundary – 4.5m - rear boundary – 4.5m. ; E4.2 For lots located in the Hamlet precinct, the minimum setback from a boundary is as follows: - road boundary - 6m - side boundary - 1.5m for lots having 1000m2 or less; 3m for lots greater than 1000m2 - rear boundary - 4m.$q$, 'VERIFIED_VERBATIM', $q$rule 14179$q$, NULL, $q$6.2.10 Rural zone code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/112/0/false/11-Sep-2026/false$q$, $q$Setback = 'shortest distance measured horizontally from the outer most projection of a building or structure to the vertical projection of the boundary of the lot' (Schedule 1).$q$, $q$mb_rural_po4_e4_setbacks_assessable$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_rural_po4_e4_setbacks_assessable", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "OTHER", "title": "Table 6.2.10.2 PO4 / E4.1 / E4.2", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DISCRETIONARY", "provision_kind": "PERFORMANCE_OUTCOME", "measurement": "SCHEME_OTHER", "operator": "=", "value": {"op": "unencoded", "text": "PO4 Setbacks are: - sufficient to minimise overlooking and maintain privacy of adjoining properties; and - sufficient to ensure development is not visually dominant or overbearing on adjoining properties. || E4.1 Unless specified elsewhere in the zone code, the minimum setback from a boundary is as follows: - road boundary – 6m - side boundary – 4.5m - rear boundary – 4.5m. ; E4.2 For lots located in the Hamlet precinct, the minimum setback from a boundary is as follows: - road boundary - 6m - side boundary - 1.5m for lots having 1000m2 or less; 3m for lots greater than 1000m2 - rear boundary - 4m.", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "ASSESS_AGAINST_PERFORMANCE_OUTCOME", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "ZONE", "zone": "CMB:RURAL"}, {"level": "PRECINCT", "precinct": "CMB:RURAL/HAMLET"}], "subjects": ["ANY"], "sources": [{"key": "mb_rural_po4_e4_setbacks_assessable", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_boundary_setback\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"E4.1: road 6m, side 4.5m, rear 4.5m\", \"E4.2 Hamlet: road 6m, side 1.5m (lot <= 1000m2) / 3m (lot > 1000m2), rear 4m\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'Assessable development (all buildings; E4.1 has no dwelling-house exclusion)' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: NO - PO4 carries no planning-scheme-matter / alternative-provision note.\nResearcher notes: Used when a RAD is not met (limited assessment against the corresponding PO; RAD3 and RAD4 -> PO4). E4.1 applies to all buildings, so the assessable benchmark is stricter than RAD3 for a dwelling house."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_rural_po4_e4_setbacks_assessable@2026-09-11$q$;
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.10.2 PO3 / E3 (repeated as PO52 / E52)$q$, 'PERFORMANCE_OUTCOME', $q$PO3 Height of buildings and structures: - is consistent with the existing low rise, open area and low density character and amenity of the Rural zone and its precincts; - does not unduly impact on access to daylight, sunlight, overshadowing or privacy experienced by adjoining premises; - for buildings in the Hamlet precinct, the height of buildings reflect the individual character of the area; - does not adversely affect the operation of aviation facility at Mt Glorious by adopting design or on-site management measures that: - ensures a physical line-of-sight between transmitting or receiving devices. - ensure electromagnetic fields do not interfere with the functioning of the aviation facility. || E3 Building height and all structures do not exceed the maximum height identified on Overlay map - Building heights; except in the Hamlet precinct, where outbuildings, free standing car ports or garages do not exceed 3.5m.$q$, 'VERIFIED_VERBATIM', $q$rule 14177$q$, NULL, $q$6.2.10 Rural zone code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/112/0/false/11-Sep-2026/false$q$, $q$Building height = vertical distance between ground level and the highest point of the building roof (apex) or parapet (Schedule 1). Mean height is not defined in the scheme (9.3.1 says it is defined in the QDC).$q$, $q$mb_rural_po3_e3_height_assessable$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_rural_po3_e3_height_assessable", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "HEIGHT.BUILDING", "title": "Table 6.2.10.2 PO3 / E3 (repeated as PO52 / E52)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DISCRETIONARY", "provision_kind": "PERFORMANCE_OUTCOME", "measurement": "SCHEME_HEIGHT", "operator": "<=", "value": {"op": "unencoded", "text": "PO3 Height of buildings and structures: - is consistent with the existing low rise, open area and low density character and amenity of the Rural zone and its precincts; - does not unduly impact on access to daylight, sunlight, overshadowing or privacy experienced by adjoining premises; - for buildings in the Hamlet precinct, the height of buildings reflect the individual character of the area; - does not adversely affect the operation of aviation facility at Mt Glorious by adopting design or on-site management measures that: - ensures a physical line-of-sight between transmitting or receiving devices. - ensure electromagnetic fields do not interfere with the functioning of the aviation facility. || E3 Building height and all structures do not exceed the maximum height identified on Overlay map - Building heights; except in the Hamlet precinct, where outbuildings, free standing car ports or garages do not exceed 3.5m.", "extracted_value": null, "extracted_operator": "<="}, "unit": "m", "on_noncompliance": "ASSESS_AGAINST_PERFORMANCE_OUTCOME", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "ZONE", "zone": "CMB:RURAL"}, {"level": "PRECINCT", "precinct": "CMB:RURAL/HAMLET"}], "subjects": ["ANY"], "sources": [{"key": "mb_rural_po3_e3_height_assessable", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"max_building_height\", \"operator\": \"<=\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"mapped Overlay map - Building heights\", \"Hamlet: outbuildings, free standing car ports or garages 3.5m\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'Buildings and structures (assessable)' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: Performance outcome / example for assessable development; RAD2 (same numbers) is the listed alternative provision."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_rural_po3_e3_height_assessable@2026-09-11$q$;
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.10.1 RAD39 (Part B PO5/E5.1, PO53/E53.1)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD39 || For Lake Samsonvale or Lake Kurwongbah, a setback of no less than 400m is maintained between the following nominated full supply levels to those lakes and any dwelling house or outbuilding on the land:- - RL 39.63m AHD being the full supply level to Lake Samsonvale; and - RL 21m AHD being the full supply level to Lake Kurwongbah. OR No part of any dwelling house or outbuilding on Lot 5 RP111651 or Lot 10 RP111653 or Lot 8 RP111268 is any closer than 80m to the full supply level of RL 21m AHD to Lake Kurwongbah. Note - This is an alternative provision to the QDC for building work associated with a Dwelling house, and is a concurrence agency issue. Editor's note - The 400m buffer around Lake Samsonvale and Lake Kurwongbah is shown on Overlay map - Infrastructure buffers$q$, 'VERIFIED_VERBATIM', $q$rule 14045$q$, NULL, $q$6.2.10 Rural zone code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/112/0/false/11-Sep-2026/false$q$, $q$$q$, $q$mb_rural_rad39_lake_setback$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_rural_rad39_lake_setback", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "OTHER", "title": "Table 6.2.10.1 RAD39 (Part B PO5/E5.1, PO53/E53.1)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_OTHER", "operator": ">=", "value": 400, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "ZONE", "zone": "CMB:RURAL"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mb_rural_rad39_lake_setback", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_setback_to_lake_full_supply_level\", \"operator\": \">=\", \"value\": 400, \"unit\": \"m\", \"conditions\": [\"Lake Samsonvale FSL RL 39.63m AHD; Lake Kurwongbah FSL RL 21m AHD\", \"Lot 5 RP111651, Lot 10 RP111653, Lot 8 RP111268: 80m to Lake Kurwongbah FSL RL 21m AHD\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'Dwelling house or outbuilding' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES - listed under 'Alternative provisions to the QDC' in the 6.2.10 'Concurrence agency issues for building work' table (RAD2, RAD8, RAD39; amenity and aesthetics column 'Nil'), and the RAD carries 'Note - This is an alternative provision to the QDC for building work associated with a Dwelling house, and is a concurrence agency issue.' Table 1.6.1 (rule 245) lists s6.2.10 as containing alternative provisions to QDC boundary clearance and site cover provisions.\nResearcher notes: 400m buffer shown on Overlay map - Infrastructure buffers."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_rural_rad39_lake_setback@2026-09-11$q$;
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.10.1 RAD1 and RAD41$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD1 || Where a development footprint has been identified as part of a development approval for reconfiguring a lot, all development occurs within the development footprint. RAD41 || Where a development footprint has been identified as part of a development approval for reconfiguring a lot, all development occurs within that development footprint.$q$, 'VERIFIED_VERBATIM', $q$rule 13991, 14047$q$, NULL, $q$6.2.10 Rural zone code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/112/0/false/11-Sep-2026/false$q$, $q$$q$, $q$mb_rural_rad1_rad41_development_footprint$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_rural_rad1_rad41_development_footprint", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "OTHER", "title": "Table 6.2.10.1 RAD1 and RAD41", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_OTHER", "operator": "=", "value": {"op": "unencoded", "text": "RAD1 || Where a development footprint has been identified as part of a development approval for reconfiguring a lot, all development occurs within the development footprint. RAD41 || Where a development footprint has been identified as part of a development approval for reconfiguring a lot, all development occurs within that development footprint.", "extracted_value": true, "extracted_operator": "=="}, "unit": null, "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "ZONE", "zone": "CMB:RURAL"}, {"level": "PRECINCT", "precinct": "CMB:RURAL/HAMLET"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mb_rural_rad1_rad41_development_footprint", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"within_development_footprint\", \"operator\": \"==\", \"value\": true, \"unit\": null, \"conditions\": [\"where a development footprint was identified in a reconfiguring a lot approval\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'All development incl. dwelling house and outbuildings' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: NO - not listed in the 6.2.10 concurrence agency issues table (only RAD2, RAD8, RAD39 are) and carries no alternative-provision note; non-compliance makes the building work assessable (limited code assessment, s5.3.3.1.a.ii) against the corresponding PO.\nResearcher notes: Where a footprint exists, RAD3 and RAD42 say they do not apply."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_rural_rad1_rad41_development_footprint@2026-09-11$q$;
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.10.1 RAD92 (Part B E100.2)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD92 || Buildings and structures have contained within the site: - a separation from classified vegetation of 20m or the distance required to achieve a bushfire attack level (BAL) at the building, roofed structure or fire fighting water supply of no more than 29, whichever is the greater; - a separation from low threat vegetation of 10m or the distance required to achieve a bushfire attack level (BAL) at the building, roofed structure or fire fighting water supply of no more than 29, whichever is the greater; - a separation of no less than 10m between a fire fighting water supply extraction point and any classified vegetation, buildings and other roofed structures; - an area suitable for a standard fire fighting appliance to stand within 3m of a fire fighting water supply extraction point; and - an access path suitable for use by a standard fire fighting appliance having a formed width of at least 4m, a cross-fall of no greater than 5%, and a longitudinal gradient of no greater than 25%: - to, and around, each building and other roofed structure; and - to each fire fighting water supply extraction point. Note - The meaning of the terms classified vegetation and low threat vegetation as well as the method of calculating the bushfire attack level are as described in Australian Standard AS 3959.$q$, 'VERIFIED_VERBATIM', $q$rule 14112$q$, NULL, $q$6.2.10 Rural zone code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/112/0/false/11-Sep-2026/false$q$, $q$$q$, $q$mb_rural_rad92_bushfire_separation$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_rural_rad92_bushfire_separation", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "SEPARATION.BUILDINGS", "title": "Table 6.2.10.1 RAD92 (Part B E100.2)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SEPARATION", "operator": ">=", "value": {"op": "unencoded", "text": "RAD92 || Buildings and structures have contained within the site: - a separation from classified vegetation of 20m or the distance required to achieve a bushfire attack level (BAL) at the building, roofed structure or fire fighting water supply of no more than 29, whichever is the greater; - a separation from low threat vegetation of 10m or the distance required to achieve a bushfire attack level (BAL) at the building, roofed structure or fire fighting water supply of no more than 29, whichever is the greater; - a separation of no less than 10m between a fire fighting water supply extraction point and any classified vegetation, buildings and other roofed structures; - an area suitable for a standard fire fighting appliance to stand within 3m of a fire fighting water supply extraction point; and - an access path suitable for use by a standard fire fighting appliance having a formed width of at least 4m, a cross-fall of no greater than 5%, and a longitudinal gradient of no greater than 25%: - to, and around, each building and other roofed structure; and - to each fire fighting water supply extraction point. Note - The meaning of the terms classified vegetation and low threat vegetation as well as the method of calculating the bushfire attack level are as described in Australian Standard AS 3959.", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "ZONE", "zone": "CMB:RURAL"}, {"level": "PRECINCT", "precinct": "CMB:RURAL/HAMLET"}, {"level": "OVERLAY", "overlay": "CMB:OV:BUSHFIRE_HAZARD"}], "subjects": ["ANY"], "sources": [{"key": "mb_rural_rad92_bushfire_separation", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_vegetation_separation\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"classified vegetation: max(20 m, distance for BAL <= 29)\", \"low threat vegetation: max(10 m, distance for BAL <= 29)\", \"fire fighting water supply extraction point >= 10 m from classified vegetation, buildings and roofed structures\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'Buildings and structures in bushfire hazard area' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: NO - values and constraints requirement; non-compliance makes the work assessable (limited code assessment) against the corresponding PO."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_rural_rad92_bushfire_separation@2026-09-11$q$;
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.10.1 RAD131$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD131 || No development is to occur within: - 50m from top of bank for W1 waterway and drainage line - 30m from top of bank for W2 waterway and drainage line - 20m from top of bank for W3 waterway and drainage line - 100m from the edge of a Ramsar wetland, 50m from all other wetlands. Note - W1, W2 and W3 waterways and drainage lines, and wetlands are mapped on Schedule 2, Section 2.5 Overlay Maps – Riparian and wetland setbacks. Note - In some cases, the top of bank may not be easily defined, as such a hydraulic measurement may be applied instead. Moreton Bay Regional Council will provide further direction on how to determine and locate the setback boundary in these locations. Note - The minimum setback distance applies to the each side of waterway.$q$, 'VERIFIED_VERBATIM', $q$rule 14159$q$, NULL, $q$6.2.10 Rural zone code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/112/0/false/11-Sep-2026/false$q$, $q$$q$, $q$mb_rural_rad131_riparian_setbacks$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_rural_rad131_riparian_setbacks", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "OTHER", "title": "Table 6.2.10.1 RAD131", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_OTHER", "operator": "=", "value": {"op": "unencoded", "text": "RAD131 || No development is to occur within: - 50m from top of bank for W1 waterway and drainage line - 30m from top of bank for W2 waterway and drainage line - 20m from top of bank for W3 waterway and drainage line - 100m from the edge of a Ramsar wetland, 50m from all other wetlands. Note - W1, W2 and W3 waterways and drainage lines, and wetlands are mapped on Schedule 2, Section 2.5 Overlay Maps – Riparian and wetland setbacks. Note - In some cases, the top of bank may not be easily defined, as such a hydraulic measurement may be applied instead. Moreton Bay Regional Council will provide further direction on how to determine and locate the setback boundary in these locations. Note - The minimum setback distance applies to the each side of waterway.", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "ZONE", "zone": "CMB:RURAL"}, {"level": "PRECINCT", "precinct": "CMB:RURAL/HAMLET"}, {"level": "OVERLAY", "overlay": "CMB:OV:RIPARIAN_AND_WETLAND_SETBACKS"}], "subjects": ["ANY"], "sources": [{"key": "mb_rural_rad131_riparian_setbacks", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_waterway_setback\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"W1 50 m, W2 30 m, W3 20 m from top of bank\", \"Ramsar wetland 100 m, other wetlands 50 m\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'All development' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: NO - values and constraints requirement; non-compliance makes the work assessable (limited code assessment) against the corresponding PO."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_rural_rad131_riparian_setbacks@2026-09-11$q$;
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$6.2.10.3 'Concurrence agency issues for building work' table$q$, 'OTHER', $q$Where building work for a Dwelling house is listed as acceptable development subject to requirements in the relevant table of assessment, but cannot comply with one or more of the Requirements for Accepted Development (RADs) listed as a concurrence agency issue in the table below, Council will undertake an assessment of those aspects of non-compliance as part of its concurrence agency role for the required building development application. In those instances, the non-compliance does not change the level of assessment, and will be assessed by Council against the performance outcome listed above for the corresponding requirements for accepted development (RAD). Where building work for a Dwelling house which would otherwise be accepted development subject to requirements cannot comply with a requirement for accepted development that is not listed as a concurrence agency issue, it becomes assessable development in accordance with section 5.3.3.1.a.ii.. Concurrence agency issues for building work Alternative provisions to the QDC || Matters that relate to amenity and aesthetics RAD2 || Nil RAD8 RAD39$q$, 'VERIFIED_VERBATIM', $q$rule 13977, 13978, 13980, 13981, 13982, 13983, 13984$q$, NULL, $q$6.2.10 Rural zone code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/112/0/false/11-Sep-2026/false$q$, $q$$q$, $q$mb_rural_concurrence_table$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_rural_concurrence_table", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "OTHER", "title": "6.2.10.3 'Concurrence agency issues for building work' table", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "OTHER", "measurement": "SCHEME_OTHER", "operator": "=", "value": {"op": "unencoded", "text": "Where building work for a Dwelling house is listed as acceptable development subject to requirements in the relevant table of assessment, but cannot comply with one or more of the Requirements for Accepted Development (RADs) listed as a concurrence agency issue in the table below, Council will undertake an assessment of those aspects of non-compliance as part of its concurrence agency role for the required building development application. In those instances, the non-compliance does not change the level of assessment, and will be assessed by Council against the performance outcome listed above for the corresponding requirements for accepted development (RAD). Where building work for a Dwelling house which would otherwise be accepted development subject to requirements cannot comply with a requirement for accepted development that is not listed as a concurrence agency issue, it becomes assessable development in accordance with section 5.3.3.1.a.ii.. Concurrence agency issues for building work Alternative provisions to the QDC || Matters that relate to amenity and aesthetics RAD2 || Nil RAD8 RAD39", "extracted_value": ["RAD2", "RAD8", "RAD39"], "extracted_operator": "in"}, "unit": null, "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "ZONE", "zone": "CMB:RURAL"}, {"level": "PRECINCT", "precinct": "CMB:RURAL/AGRICULTURE"}, {"level": "PRECINCT", "precinct": "CMB:RURAL/HAMLET"}, {"level": "PRECINCT", "precinct": "CMB:RURAL/RURAL_LIVING_INVESTIGATION"}, {"level": "PRECINCT", "precinct": "CMB:RURAL/WOODFORDIA_ABBEY"}, {"level": "PRECINCT", "precinct": "CMB:RURAL/CEDARTON_MT_NEBO"}], "subjects": ["CLASS_1"], "sources": [{"key": "mb_rural_concurrence_table", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"concurrence_agency_rads\", \"operator\": \"in\", \"value\": [\"RAD2\", \"RAD8\", \"RAD39\"], \"unit\": null, \"conditions\": [\"amenity and aesthetics: Nil\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'Building work for a Dwelling house' mapped by keyword to ['CLASS_1']\nAlternative provision to QDC/QHC: Defines the alternative provisions for 6.2.10: RAD2 (height), RAD8 (car parking), RAD39 (lake setback).\nResearcher notes: No site cover or roofed-area limit exists anywhere in the Rural zone code, so site cover falls to the QDC/QHC. Table 1.6.1 rule 247 lists 6.2.10 for amenity/aesthetic provisions, but this table says Nil. 6.2.10.1 (rule 13814): 'Development associated with a dwelling house is subject to the relevant provisions in this code and not the dwelling house code.'"}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_rural_concurrence_table@2026-09-11$q$;
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.12.3.1 RAD1 (Part F PO3/E3)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD1 || Building height does not exceed that mapped on Overlay map - Building heights. Note - The above does not apply to domestic outbuildings. Refer to requirements for Domestic outbuildings in this code.$q$, 'VERIFIED_VERBATIM', $q$rule 16151$q$, NULL, $q$6.2.12 Township zone code (6.2.12.3 Township residential precinct)$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/125/0/false/11-Sep-2026/false$q$, $q$Building height = vertical distance between ground level and the highest point of the building roof (apex) or parapet (Schedule 1). Mean height is not defined in the scheme (9.3.1 says it is defined in the QDC).$q$, $q$mb_tw_rad1_height_dwelling$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_tw_rad1_height_dwelling", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "HEIGHT.BUILDING", "title": "Table 6.2.12.3.1 RAD1 (Part F PO3/E3)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_HEIGHT", "operator": "<=", "value": {"op": "unencoded", "text": "RAD1 || Building height does not exceed that mapped on Overlay map - Building heights. Note - The above does not apply to domestic outbuildings. Refer to requirements for Domestic outbuildings in this code.", "extracted_value": null, "extracted_operator": "<="}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:TOWNSHIP/TOWNSHIP_RESIDENTIAL"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mb_tw_rad1_height_dwelling", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"max_building_height\", \"operator\": \"<=\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"value = maximum mapped on Overlay map - Building heights (open data suggests Max 8.5m)\"], \"exceptions\": [\"domestic outbuildings use RAD59\"], \"formula_text\": null}\nStructure scope 'Dwelling house (not domestic outbuildings)' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: NO - no alternative-provision / concurrence note on this RAD (6.2.12.3 has no 'Concurrence agency issues' table); non-compliance makes the building work assessable (limited code assessment, s5.3.3.1.a.ii) against the corresponding PO.\nResearcher notes: Mapped value from Overlay map - Building heights. Spot check of council open-data layer OM_Building_Heights_WebMercator_OpenData (2022 data, not the legal V8 map) at 40 random parcel centroids per area: Township residential 40/40 'Max 8.5m'; Rural (no precinct) 38/40 'Max 8.5m' and 2 outside any polygon; Hamlet 40/40 'Max 8.5m'; Agriculture 40/40 'Max 8.5m'. Check each lot."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_tw_rad1_height_dwelling@2026-09-11$q$;
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.12.3.1 RAD3(a) setback table$q$, 'TABLE', $q$RAD3 || Setbacks: - comply with the table below; or Setbacks ; Height of wall || Frontage Primary || Frontage Secondary to street || Side To OMP and wall || Rear To OMP and wall ; To wall || To OMP || To car parking space and domestic outbuildings || To wall || To OMP || To car parking space and domestic outbuildings ; Less than 4.5m || Min 6.0m || Min 4.5m || Min 5.4 || Min 3m || Min 2m || Min 5.4 || Min 1.5m || Refer to standards in QDC ; 4.5m or more || Min 6.0m || Min 4.5m || N/A || Min 3m || Min 2m || N/A || Min 2m || Refer to standards in QDC ; Note - Greater setbacks may be required if the lot adjoins an environmental corridor or area (Refer to values and constraints for details). - for carports associated with a Dwelling house that remain open and are not enclosed by walls, screens or the like the following applies: - if the Dwelling house was built before 2005: not less than the setback to an existing lawfully constructed carport or garage on an adjoining lot with the same road frontage (where a lawfully constructed carport or garage is located on both sides, the lesser of the two is applicable); or 0.5m whichever is the greater; or - in all other instances: a minimum setback of 5.4m from the primary or secondary frontage. Note - This is an alternative provision to the QDC for building work associated with a Dwelling house, and is a concurrence agency issue.$q$, 'VERIFIED_VERBATIM', $q$rule 31128$q$, NULL, $q$6.2.12 Township zone code (6.2.12.3 Township residential precinct)$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/125/0/false/11-Sep-2026/false$q$, $q$Setback = 'shortest distance measured horizontally from the outer most projection of a building or structure to the vertical projection of the boundary of the lot' (Schedule 1). Columns: Height of wall || Frontage Primary [To wall | To OMP | To car parking space and domestic outbuildings] || Frontage Secondary to street [To wall | To OMP | To car parking space and domestic outbuildings] || Side To OMP and wall || Rear To OMP and wall (column spans checked in source HTML). 'Height of wall' is not defined.$q$, $q$mb_tw_rad3_primary_frontage$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_tw_rad3_primary_frontage", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "SETBACK.FRONTAGE", "title": "Table 6.2.12.3.1 RAD3(a) setback table", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "TABLE", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": {"op": "unencoded", "text": "select row by height of wall; apply both to-wall and to-OMP minimums", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:TOWNSHIP/TOWNSHIP_RESIDENTIAL"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mb_tw_rad3_primary_frontage", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_primary_frontage_setback\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"wall height < 4.5 m: to wall Min 6.0m, to OMP Min 4.5m, to car parking space and domestic outbuildings Min 5.4\", \"wall height >= 4.5 m: to wall Min 6.0m, to OMP Min 4.5m, car parking/outbuildings N/A\"], \"exceptions\": [\"open carports: RAD3(b) (separate record)\", \"greater setbacks may be required next to an environmental corridor or area\"], \"formula_text\": \"select row by height of wall; apply both to-wall and to-OMP minimums\"}\nStructure scope 'Class 1a dwelling house and Class 10a (car parking space, domestic outbuildings)' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES - carries 'Note - This is an alternative provision to the QDC for building work associated with a Dwelling house, and is a concurrence agency issue.' CAUTION: Table 1.6.1 (rules 245/246) names only s6.2.10, s6.2.11 and s9.3.1 as containing alternative provisions; s6.2.12 is named only in s1.6 (rule 248) as a code containing 'concurrence agency issues'.\nResearcher notes: RAD59(c) also requires domestic outbuildings to be behind the main building line and outside the frontage setbacks (except a complying carport)."}$q$::jsonb);
