SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.12.3.1 RAD3(b)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD3 || Setbacks: - comply with the table below; or Setbacks ; Height of wall || Frontage Primary || Frontage Secondary to street || Side To OMP and wall || Rear To OMP and wall ; To wall || To OMP || To car parking space and domestic outbuildings || To wall || To OMP || To car parking space and domestic outbuildings ; Less than 4.5m || Min 6.0m || Min 4.5m || Min 5.4 || Min 3m || Min 2m || Min 5.4 || Min 1.5m || Refer to standards in QDC ; 4.5m or more || Min 6.0m || Min 4.5m || N/A || Min 3m || Min 2m || N/A || Min 2m || Refer to standards in QDC ; Note - Greater setbacks may be required if the lot adjoins an environmental corridor or area (Refer to values and constraints for details). - for carports associated with a Dwelling house that remain open and are not enclosed by walls, screens or the like the following applies: - if the Dwelling house was built before 2005: not less than the setback to an existing lawfully constructed carport or garage on an adjoining lot with the same road frontage (where a lawfully constructed carport or garage is located on both sides, the lesser of the two is applicable); or 0.5m whichever is the greater; or - in all other instances: a minimum setback of 5.4m from the primary or secondary frontage. Note - This is an alternative provision to the QDC for building work associated with a Dwelling house, and is a concurrence agency issue.$q$, 'VERIFIED_VERBATIM', $q$rule 31128$q$, NULL, $q$6.2.12 Township zone code (6.2.12.3 Township residential precinct)$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/125/0/false/11-Sep-2026/false$q$, $q$Setback = 'shortest distance measured horizontally from the outer most projection of a building or structure to the vertical projection of the boundary of the lot' (Schedule 1).$q$, $q$mb_tw_rad3_carport_frontage$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_tw_rad3_carport_frontage", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "GARAGE.FRONTAGE", "title": "Table 6.2.12.3.1 RAD3(b)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_GARAGE_CARPORT", "operator": ">=", "value": {"op": "unencoded", "text": "pre-2005: max(adjoining carport/garage setback [lesser of two], 0.5); else 5.4", "extracted_value": 5.4, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:TOWNSHIP/TOWNSHIP_RESIDENTIAL"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mb_tw_rad3_carport_frontage", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_carport_frontage_setback\", \"operator\": \"conditional\", \"value\": 5.4, \"unit\": \"m\", \"conditions\": [\"dwelling house built before 2005: not less than the setback to an existing lawfully constructed carport or garage on an adjoining lot with the same road frontage (lesser of the two if on both sides), or 0.5m, whichever is greater\", \"all other instances: min 5.4m from the primary or secondary frontage\"], \"exceptions\": [], \"formula_text\": \"pre-2005: max(adjoining carport/garage setback [lesser of two], 0.5); else 5.4\"}\nStructure scope 'Open carports (not enclosed by walls, screens or the like) associated with a Dwelling house' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES - carries 'Note - This is an alternative provision to the QDC for building work associated with a Dwelling house, and is a concurrence agency issue.' CAUTION: Table 1.6.1 (rules 245/246) names only s6.2.10, s6.2.11 and s9.3.1 as containing alternative provisions; s6.2.12 is named only in s1.6 (rule 248) as a code containing 'concurrence agency issues'.\nResearcher notes: RAD3 reads 'Setbacks: (a) comply with the table below; or (b) for carports ...', so the carport limb is an alternative to the table."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_tw_rad3_carport_frontage@2026-09-11$q$;
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.12.3.1 RAD4 (Part F PO5/E5)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD4 || Site cover does not exceed 50% (excluding eaves, sun shading devices, patios, balconies and other unenclosed structures).$q$, 'VERIFIED_VERBATIM', $q$rule 16158$q$, NULL, $q$6.2.12 Township zone code (6.2.12.3 Township residential precinct)$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/125/0/false/11-Sep-2026/false$q$, $q$Site cover (Schedule 1) includes carports and is calculated to outermost projections, but RAD4 excludes 'other unenclosed structures', so the treatment of open carports is ambiguous.$q$, $q$mb_tw_rad4_site_cover$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_tw_rad4_site_cover", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "SITE_COVER", "title": "Table 6.2.12.3.1 RAD4 (Part F PO5/E5)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SITE_COVER", "operator": "<=", "value": 50, "unit": "%", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:TOWNSHIP/TOWNSHIP_RESIDENTIAL"}], "subjects": ["ANY"], "sources": [{"key": "mb_tw_rad4_site_cover", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"max_site_cover\", \"operator\": \"<=\", \"value\": 50, \"unit\": \"%\", \"conditions\": [], \"exceptions\": [\"eaves\", \"sun shading devices\", \"patios\", \"balconies\", \"other unenclosed structures\"], \"formula_text\": null}\nStructure scope 'All buildings incl. domestic outbuildings (excluding unenclosed structures)' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: NO - no alternative-provision / concurrence note on this RAD (6.2.12.3 has no 'Concurrence agency issues' table); non-compliance makes the building work assessable (limited code assessment, s5.3.3.1.a.ii) against the corresponding PO.\nResearcher notes: RAD4 has no alternative-provision note (unlike RAD3/RAD59), so exceeding site cover appears to trigger code assessment rather than concurrence. Confirm whether Council treats it as a QDC/QHC alternative."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_tw_rad4_site_cover@2026-09-11$q$;
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.12.3.1 RAD46 (Part F PO54/E54)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD46 || Garage and carport openings, where within the first 20m of the site frontage are no greater than: ; Primary or secondary frontage || Covered car space opening(s) per street frontage And location of car parking areas ; Greater than 18m || Not specified ; Greater than 12.5m to 18m || 6m wide maximum ; 12.5m or less || Single storey dwelling: 3.0m wide maximum; Double storey dwelling: 6.0m wide maximum and recessed 1.0m behind the front wall or balcony of upper level. ; Note - Refer to Planning scheme policy - Residential design for details and examples.$q$, 'VERIFIED_VERBATIM', $q$rule 31135$q$, NULL, $q$6.2.12 Township zone code (6.2.12.3 Township residential precinct)$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/125/0/false/11-Sep-2026/false$q$, $q$$q$, $q$mb_tw_rad46_garage_openings$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_tw_rad46_garage_openings", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "GARAGE.FRONTAGE", "title": "Table 6.2.12.3.1 RAD46 (Part F PO54/E54)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_GARAGE_CARPORT", "operator": ">=", "value": {"op": "unencoded", "text": "RAD46 || Garage and carport openings, where within the first 20m of the site frontage are no greater than: ; Primary or secondary frontage || Covered car space opening(s) per street frontage And location of car parking areas ; Greater than 18m || Not specified ; Greater than 12.5m to 18m || 6m wide maximum ; 12.5m or less || Single storey dwelling: 3.0m wide maximum; Double storey dwelling: 6.0m wide maximum and recessed 1.0m behind the front wall or balcony of upper level. ; Note - Refer to Planning scheme policy - Residential design for details and examples.", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:TOWNSHIP/TOWNSHIP_RESIDENTIAL"}], "subjects": ["CLASS_10A"], "sources": [{"key": "mb_tw_rad46_garage_openings", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"max_garage_opening_width\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"frontage > 18m: not specified\", \"frontage > 12.5m to 18m: 6m wide maximum\", \"frontage <= 12.5m: single storey 3.0m max; double storey 6.0m max and recessed 1.0m behind the front wall or upper-level balcony\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): Primary or secondary frontage width bands: Greater than 18m; Greater than 12.5m to 18m; 12.5m or less\nStructure scope 'Garage and carport openings within the first 20m of the site frontage' mapped by keyword to ['CLASS_10A']\nAlternative provision to QDC/QHC: NO - no alternative-provision / concurrence note on this RAD (6.2.12.3 has no 'Concurrence agency issues' table); non-compliance makes the building work assessable (limited code assessment, s5.3.3.1.a.ii) against the corresponding PO."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_tw_rad46_garage_openings@2026-09-11$q$;
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.12.3.1 RAD59(a)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD59 || Domestic outbuildings: - have a total combined maximum roofed area as outlined in the table below: ; Size of lot || Maximum roofed area ; Less than 600m2 || 50m2 ; 600m2 - 1000m2 || 70m2 ; >1000m2 – 2000m2 || 80m2 ; Greater than 2000m2 || 150m2 ; - have a maximum building height as follows; - where in front of the main building line for a carport - have a maximum building height of 3.3m and a mean height not exceeding 2.7m; or - for all other instances - have a maximum building height of 4m and a mean height not exceeding 3.5m; - are located behind the main building line and not within the primary frontage, secondary frontage or trafficable water body setbacks except where for a carport and complying with the front setback for carports specified in this code. Note - For c. above the building line of a trafficable water body boundary is to be treated the same as a secondary frontage. Note - Except for the matters outlined in a. above, this is an alternative provision to the QDC for building work associated with a Dwelling house, and is a concurrence agency issue.$q$, 'VERIFIED_VERBATIM', $q$rule 31136$q$, NULL, $q$6.2.12 Township zone code (6.2.12.3 Township residential precinct)$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/125/0/false/11-Sep-2026/false$q$, $q$Roofed area = area of the roof of each building or structure projected onto a horizontal plane; the limit is the total combined roofed area of all domestic outbuildings.$q$, $q$mb_tw_rad59_outbuilding_roofed_area$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_tw_rad59_outbuilding_roofed_area", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "OUTBUILDING.SIZE", "title": "Table 6.2.12.3.1 RAD59(a)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_OUTBUILDING_SIZE", "operator": "<=", "value": {"op": "unencoded", "text": "RAD59 || Domestic outbuildings: - have a total combined maximum roofed area as outlined in the table below: ; Size of lot || Maximum roofed area ; Less than 600m2 || 50m2 ; 600m2 - 1000m2 || 70m2 ; >1000m2 – 2000m2 || 80m2 ; Greater than 2000m2 || 150m2 ; - have a maximum building height as follows; - where in front of the main building line for a carport - have a maximum building height of 3.3m and a mean height not exceeding 2.7m; or - for all other instances - have a maximum building height of 4m and a mean height not exceeding 3.5m; - are located behind the main building line and not within the primary frontage, secondary frontage or trafficable water body setbacks except where for a carport and complying with the front setback for carports specified in this code. Note - For c. above the building line of a trafficable water body boundary is to be treated the same as a secondary frontage. Note - Except for the matters outlined in a. above, this is an alternative provision to the QDC for building work associated with a Dwelling house, and is a concurrence agency issue.", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m2", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:TOWNSHIP/TOWNSHIP_RESIDENTIAL"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mb_tw_rad59_outbuilding_roofed_area", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"max_total_outbuilding_roofed_area\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m2\", \"conditions\": [\"lot < 600 m2: 50m2\", \"600 m2 - 1000 m2: 70m2\", \"> 1000 m2 - 2000 m2: 80m2\", \"> 2000 m2: 150m2\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): Less than 600m2 | 600m2 - 1000m2 | >1000m2 - 2000m2 | Greater than 2000m2\nStructure scope 'Domestic outbuildings (Class 10a shed, garage, carport)' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: NO - RAD59 note: 'Except for the matters outlined in a. above, this is an alternative provision to the QDC'. The roofed-area limb (a) is excluded, so non-compliance makes the work assessable (limited code assessment).\nResearcher notes: Band edges as written: '600m2 - 1000m2' then '>1000m2 - 2000m2' (1000m2 falls in the 70m2 band). Part F E64 labels the same column 'Max. GFA' instead of 'Maximum roofed area'."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_tw_rad59_outbuilding_roofed_area@2026-09-11$q$;
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.12.3.1 RAD59(b)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD59 || Domestic outbuildings: - have a total combined maximum roofed area as outlined in the table below: ; Size of lot || Maximum roofed area ; Less than 600m2 || 50m2 ; 600m2 - 1000m2 || 70m2 ; >1000m2 – 2000m2 || 80m2 ; Greater than 2000m2 || 150m2 ; - have a maximum building height as follows; - where in front of the main building line for a carport - have a maximum building height of 3.3m and a mean height not exceeding 2.7m; or - for all other instances - have a maximum building height of 4m and a mean height not exceeding 3.5m; - are located behind the main building line and not within the primary frontage, secondary frontage or trafficable water body setbacks except where for a carport and complying with the front setback for carports specified in this code. Note - For c. above the building line of a trafficable water body boundary is to be treated the same as a secondary frontage. Note - Except for the matters outlined in a. above, this is an alternative provision to the QDC for building work associated with a Dwelling house, and is a concurrence agency issue.$q$, 'VERIFIED_VERBATIM', $q$rule 31136$q$, NULL, $q$6.2.12 Township zone code (6.2.12.3 Township residential precinct)$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/125/0/false/11-Sep-2026/false$q$, $q$Building height = vertical distance between ground level and the highest point of the building roof (apex) or parapet (Schedule 1). Mean height is not defined in the scheme (9.3.1 says it is defined in the QDC).$q$, $q$mb_tw_rad59_outbuilding_height$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_tw_rad59_outbuilding_height", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "HEIGHT.BUILDING", "title": "Table 6.2.12.3.1 RAD59(b)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_HEIGHT", "operator": "<=", "value": {"op": "unencoded", "text": "RAD59 || Domestic outbuildings: - have a total combined maximum roofed area as outlined in the table below: ; Size of lot || Maximum roofed area ; Less than 600m2 || 50m2 ; 600m2 - 1000m2 || 70m2 ; >1000m2 – 2000m2 || 80m2 ; Greater than 2000m2 || 150m2 ; - have a maximum building height as follows; - where in front of the main building line for a carport - have a maximum building height of 3.3m and a mean height not exceeding 2.7m; or - for all other instances - have a maximum building height of 4m and a mean height not exceeding 3.5m; - are located behind the main building line and not within the primary frontage, secondary frontage or trafficable water body setbacks except where for a carport and complying with the front setback for carports specified in this code. Note - For c. above the building line of a trafficable water body boundary is to be treated the same as a secondary frontage. Note - Except for the matters outlined in a. above, this is an alternative provision to the QDC for building work associated with a Dwelling house, and is a concurrence agency issue.", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:TOWNSHIP/TOWNSHIP_RESIDENTIAL"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mb_tw_rad59_outbuilding_height", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"max_outbuilding_height\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"carport in front of the main building line: max building height 3.3m and mean height <= 2.7m\", \"all other instances: max building height 4m and mean height <= 3.5m\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'Domestic outbuildings (Class 10a shed, garage, carport)' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES - carries 'Note - This is an alternative provision to the QDC for building work associated with a Dwelling house, and is a concurrence agency issue.' CAUTION: Table 1.6.1 (rules 245/246) names only s6.2.10, s6.2.11 and s9.3.1 as containing alternative provisions; s6.2.12 is named only in s1.6 (rule 248) as a code containing 'concurrence agency issues'.\nResearcher notes: Part F E3 (assessable) gives only 4m / mean 3.5m for domestic outbuildings including free standing carports and garages; E64 repeats the 3.3m/2.7m carport limb."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_tw_rad59_outbuilding_height@2026-09-11$q$;
INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CMB.mb_tw_rad59_outbuilding_height@2026-09-11$q$, $q$QDC12.A4.BUILDING_HEIGHT$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CMB.mb_tw_rad59_outbuilding_height@2026-09-11$q$, $q$QDC11.A4.BUILDING_HEIGHT$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.12.3.1 RAD59(c)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD59 || Domestic outbuildings: - have a total combined maximum roofed area as outlined in the table below: ; Size of lot || Maximum roofed area ; Less than 600m2 || 50m2 ; 600m2 - 1000m2 || 70m2 ; >1000m2 – 2000m2 || 80m2 ; Greater than 2000m2 || 150m2 ; - have a maximum building height as follows; - where in front of the main building line for a carport - have a maximum building height of 3.3m and a mean height not exceeding 2.7m; or - for all other instances - have a maximum building height of 4m and a mean height not exceeding 3.5m; - are located behind the main building line and not within the primary frontage, secondary frontage or trafficable water body setbacks except where for a carport and complying with the front setback for carports specified in this code. Note - For c. above the building line of a trafficable water body boundary is to be treated the same as a secondary frontage. Note - Except for the matters outlined in a. above, this is an alternative provision to the QDC for building work associated with a Dwelling house, and is a concurrence agency issue.$q$, 'VERIFIED_VERBATIM', $q$rule 31136$q$, NULL, $q$6.2.12 Township zone code (6.2.12.3 Township residential precinct)$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/125/0/false/11-Sep-2026/false$q$, $q$Main building line = line extending from the longest wall (excluding a garage, carport or other domestic outbuilding) in the front elevation. A trafficable water body boundary is treated the same as a secondary frontage.$q$, $q$mb_tw_rad59_outbuilding_location$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_tw_rad59_outbuilding_location", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "SETBACK.FRONTAGE", "title": "Table 6.2.12.3.1 RAD59(c)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": {"op": "unencoded", "text": "RAD59 || Domestic outbuildings: - have a total combined maximum roofed area as outlined in the table below: ; Size of lot || Maximum roofed area ; Less than 600m2 || 50m2 ; 600m2 - 1000m2 || 70m2 ; >1000m2 – 2000m2 || 80m2 ; Greater than 2000m2 || 150m2 ; - have a maximum building height as follows; - where in front of the main building line for a carport - have a maximum building height of 3.3m and a mean height not exceeding 2.7m; or - for all other instances - have a maximum building height of 4m and a mean height not exceeding 3.5m; - are located behind the main building line and not within the primary frontage, secondary frontage or trafficable water body setbacks except where for a carport and complying with the front setback for carports specified in this code. Note - For c. above the building line of a trafficable water body boundary is to be treated the same as a secondary frontage. Note - Except for the matters outlined in a. above, this is an alternative provision to the QDC for building work associated with a Dwelling house, and is a concurrence agency issue.", "extracted_value": true, "extracted_operator": "=="}, "unit": null, "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:TOWNSHIP/TOWNSHIP_RESIDENTIAL"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mb_tw_rad59_outbuilding_location", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"outbuilding_behind_main_building_line\", \"operator\": \"==\", \"value\": true, \"unit\": null, \"conditions\": [\"not within the primary frontage, secondary frontage or trafficable water body setbacks\"], \"exceptions\": [\"carport complying with the RAD3(b) carport front setback\"], \"formula_text\": null}\nStructure scope 'Domestic outbuildings (Class 10a shed, garage, carport)' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES - carries 'Note - This is an alternative provision to the QDC for building work associated with a Dwelling house, and is a concurrence agency issue.' CAUTION: Table 1.6.1 (rules 245/246) names only s6.2.10, s6.2.11 and s9.3.1 as containing alternative provisions; s6.2.12 is named only in s1.6 (rule 248) as a code containing 'concurrence agency issues'."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_tw_rad59_outbuilding_location@2026-09-11$q$;
INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CMB.mb_tw_rad59_outbuilding_location@2026-09-11$q$, $q$QDC12.A1a.ROAD_SETBACK$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CMB.mb_tw_rad59_outbuilding_location@2026-09-11$q$, $q$QDC11.A1a.FRONTAGE_SETBACK$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.12.3.2 PO3 / E3$q$, 'PERFORMANCE_OUTCOME', $q$PO3 Building height - is consistent with the low rise character of the Township precinct; - preserves the natural features of the site, including slope, orientation and view corridors; - does not unduly impact on views, breezes, sunlight or privacy experienced by adjoining properties. || E3 Building height does not exceed: - that mapped on Overlay map – Building heights; or - for domestic outbuildings, including free standing carports and garages, 4m and a mean height not exceeding 3.5m.$q$, 'VERIFIED_VERBATIM', $q$rule 16290$q$, NULL, $q$6.2.12 Township zone code (6.2.12.3 Township residential precinct)$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/125/0/false/11-Sep-2026/false$q$, $q$Building height = vertical distance between ground level and the highest point of the building roof (apex) or parapet (Schedule 1). Mean height is not defined in the scheme (9.3.1 says it is defined in the QDC).$q$, $q$mb_tw_e3_height_assessable$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_tw_e3_height_assessable", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "HEIGHT.BUILDING", "title": "Table 6.2.12.3.2 PO3 / E3", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DISCRETIONARY", "provision_kind": "PERFORMANCE_OUTCOME", "measurement": "SCHEME_HEIGHT", "operator": "<=", "value": 4, "unit": "m", "on_noncompliance": "ASSESS_AGAINST_PERFORMANCE_OUTCOME", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:TOWNSHIP/TOWNSHIP_RESIDENTIAL"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mb_tw_e3_height_assessable", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"max_outbuilding_height\", \"operator\": \"<=\", \"value\": 4, \"unit\": \"m\", \"conditions\": [\"dwelling: mapped Overlay map - Building heights\", \"domestic outbuildings: 4m and mean height <= 3.5m\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'Dwelling house; domestic outbuildings incl. free standing carports and garages (assessable)' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: NO - performance outcome / example for assessable development; no note."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_tw_e3_height_assessable@2026-09-11$q$;
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.12.3.2 PO4 / E4$q$, 'PERFORMANCE_OUTCOME', $q$PO4 Setbacks are: - consistent with the low density Township character where buildings are positioned further away from the footpath and further apart from each other; - provide area on-site that is unconstrained by buildings and structures; - ensure parked vehicles do not restrict pedestrian and traffic movement and safety; - maintain the privacy of residents and adjoining properties; - maintain private open space areas that are of a size and shape that is useable and functional; - ensure covered car parking spaces and domestic outbuildings that are visible from the street or public space: - visually integrate with the dwelling house; Note - For example, materials, colours, finishes and roof form are consistent with the existing dwelling. - are of a scale, location and built form that contributes positively to the streetscape; - have a design and built form that complements the low density character of the precinct; - are consistent with the established character of the precinct and avoid dominating or otherwise negatively impacting the streetscape or adjoining properties’. || E4 Setbacks: - comply with the table below; or Setbacks ; Height of wall || Frontage Primary || Frontage Secondary to street || Side To OMP and wall || Rear To OMP and wall ; To wall || To OMP || To car parking space and domestic outbuildings || To wall || To OMP || To car parking space and domestic outbuildings ; Less than 4.5m || Min 6.0m || Min 4.5m || Min 5.4 || Min 3m || Min 2m || Min 5.4 || Min 1.5m || 6.0m ; 4.5m or more || Min 6.0m || Min 4.5m || N/A || Min 3m || Min 2m || N/A || Min 2m || 6.0m ; Note - Greater setbacks may be required if the lot adjoins an environmental corridor or area (Refer to values and constraints for details). - for carports associated with a Dwelling house that remain open and are not enclosed by walls, screens or the like the following applies: - if the Dwelling house was built before 2005: not less than the setback to an existing lawfully constructed carport or garage on an adjoining lot have the same road frontage (where a lawfully constructed carport or garage is located on both sides, the lesser of the two is applicable); or 0.5m whichever is the greater; or - in all other instances: a minimum setback of 5.4m from the primary or secondary frontage. Note - This is an alternative provision to the QDC for building work associated with a Dwelling house, and is a concurrence agency issue.$q$, 'VERIFIED_VERBATIM', $q$rule 31138$q$, NULL, $q$6.2.12 Township zone code (6.2.12.3 Township residential precinct)$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/125/0/false/11-Sep-2026/false$q$, $q$Setback = 'shortest distance measured horizontally from the outer most projection of a building or structure to the vertical projection of the boundary of the lot' (Schedule 1).$q$, $q$mb_tw_e4_rear_assessable$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_tw_e4_rear_assessable", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "SETBACK.REAR", "title": "Table 6.2.12.3.2 PO4 / E4", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DISCRETIONARY", "provision_kind": "PERFORMANCE_OUTCOME", "measurement": "SCHEME_SETBACK_REAR", "operator": ">=", "value": 6.0, "unit": "m", "on_noncompliance": "ASSESS_AGAINST_PERFORMANCE_OUTCOME", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:TOWNSHIP/TOWNSHIP_RESIDENTIAL"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mb_tw_e4_rear_assessable", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_rear_setback\", \"operator\": \">=\", \"value\": 6.0, \"unit\": \"m\", \"conditions\": [\"both wall-height rows: 6.0m\", \"other columns identical to RAD3 (primary 6.0/4.5/5.4; secondary 3/2/5.4; side 1.5 or 2)\"], \"exceptions\": [\"open carports per the E4 carport limb\"], \"formula_text\": null}\nStructure scope 'Dwelling house and Class 10a (assessable)' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: E4 carries the same 'alternative provision to the QDC ... concurrence agency issue' note as RAD3.\nResearcher notes: Conflict: RAD3 rear column = 'Refer to standards in QDC'; E4 rear column = '6.0m'. A building that fails RAD3 is assessed against PO4, for which E4 is only an example."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_tw_e4_rear_assessable@2026-09-11$q$;
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.12.3.2 PO5 / E5$q$, 'PERFORMANCE_OUTCOME', $q$PO5 Site cover: - reduces the dominance of buildings and structures to reflect the detached, low density Township character; - provides generous open areas around buildings for usable private open space, protect existing vegetation and enable ‘private’ greening of yard space; - reduces building bulk and creates visual interest in the built form; - maximises separation between buildings to maximise amenity, cross ventilation and solar access. || E5 Site cover does not exceed 50% (excluding eaves, sun shading devices, patios, balconies and other unenclosed structures).$q$, 'VERIFIED_VERBATIM', $q$rule 16295$q$, NULL, $q$6.2.12 Township zone code (6.2.12.3 Township residential precinct)$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/125/0/false/11-Sep-2026/false$q$, $q$$q$, $q$mb_tw_e5_site_cover_assessable$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_tw_e5_site_cover_assessable", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "SITE_COVER", "title": "Table 6.2.12.3.2 PO5 / E5", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DISCRETIONARY", "provision_kind": "PERFORMANCE_OUTCOME", "measurement": "SCHEME_SITE_COVER", "operator": "<=", "value": 50, "unit": "%", "on_noncompliance": "ASSESS_AGAINST_PERFORMANCE_OUTCOME", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:TOWNSHIP/TOWNSHIP_RESIDENTIAL"}], "subjects": ["ANY"], "sources": [{"key": "mb_tw_e5_site_cover_assessable", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"max_site_cover\", \"operator\": \"<=\", \"value\": 50, \"unit\": \"%\", \"conditions\": [], \"exceptions\": [\"eaves, sun shading devices, patios, balconies and other unenclosed structures\"], \"formula_text\": null}\nStructure scope 'All buildings (assessable)' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: NO - performance outcome / example for assessable development; no note."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_tw_e5_site_cover_assessable@2026-09-11$q$;
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.12.3.2 PO64 / E64$q$, 'PERFORMANCE_OUTCOME', $q$PO64 Domestic outbuildings and car ports are: - of a height that does not negatively impact the visual amenity of adjoining properties; - ensure covered car parking spaces and domestic outbuildings that are visible from the street or public space - visually integrate with the dwelling house; Note - For example, materials, colours, finishes and roof form are consistent with the existing dwelling. - are of a scale, location and built form that contributes positively to the streetscape; - have a design and built form that complements the low density character of the precinct; - are consistent with the established character of the precinct and avoid dominating or otherwise negatively impacting the streetscape or adjoining properties’. || E64 Domestic outbuildings: - have a total combined maximum roofed area as outlined in the table below: ; Size of lot || Max. GFA ; Less than 600m2 || 50m2 ; 600m2 - 1000m2 || 70m2 ; Greater than 1000m2 – 2000m2 || 80m2 ; Greater than 2000m2 || 150m2 ; - have a maximum building height as follows: - where in front of the main building line for a carport - have a maximum building height of 3.3m and a mean height not exceeding 2.7m; or - for all other instances - have a maximum building height of 4m and a mean height not exceeding 3.5m; - are located behind the main building line and not within primary or secondary frontage or trafficable water body setbacks except where for a carport and complying with the front setback for carports associated with a Dwelling house specified in this code. Note - For c. above to determine the main building line a trafficable water body boundary is to be treated the same as a secondary frontage. Note - Except for the matters outlined in a. above, this is an alternative provision to the QDC for building work associated with a Dwelling house, and is a concurrence agency issue.$q$, 'VERIFIED_VERBATIM', $q$rule 31147$q$, NULL, $q$6.2.12 Township zone code (6.2.12.3 Township residential precinct)$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/125/0/false/11-Sep-2026/false$q$, $q$$q$, $q$mb_tw_e64_outbuildings_assessable$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_tw_e64_outbuildings_assessable", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "OUTBUILDING.SIZE", "title": "Table 6.2.12.3.2 PO64 / E64", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DISCRETIONARY", "provision_kind": "PERFORMANCE_OUTCOME", "measurement": "SCHEME_OUTBUILDING_SIZE", "operator": "<=", "value": {"op": "unencoded", "text": "PO64 Domestic outbuildings and car ports are: - of a height that does not negatively impact the visual amenity of adjoining properties; - ensure covered car parking spaces and domestic outbuildings that are visible from the street or public space - visually integrate with the dwelling house; Note - For example, materials, colours, finishes and roof form are consistent with the existing dwelling. - are of a scale, location and built form that contributes positively to the streetscape; - have a design and built form that complements the low density character of the precinct; - are consistent with the established character of the precinct and avoid dominating or otherwise negatively impacting the streetscape or adjoining properties’. || E64 Domestic outbuildings: - have a total combined maximum roofed area as outlined in the table below: ; Size of lot || Max. GFA ; Less than 600m2 || 50m2 ; 600m2 - 1000m2 || 70m2 ; Greater than 1000m2 – 2000m2 || 80m2 ; Greater than 2000m2 || 150m2 ; - have a maximum building height as follows: - where in front of the main building line for a carport - have a maximum building height of 3.3m and a mean height not exceeding 2.7m; or - for all other instances - have a maximum building height of 4m and a mean height not exceeding 3.5m; - are located behind the main building line and not within primary or secondary frontage or trafficable water body setbacks except where for a carport and complying with the front setback for carports associated with a Dwelling house specified in this code. Note - For c. above to determine the main building line a trafficable water body boundary is to be treated the same as a secondary frontage. Note - Except for the matters outlined in a. above, this is an alternative provision to the QDC for building work associated with a Dwelling house, and is a concurrence agency issue.", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m2", "on_noncompliance": "ASSESS_AGAINST_PERFORMANCE_OUTCOME", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:TOWNSHIP/TOWNSHIP_RESIDENTIAL"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mb_tw_e64_outbuildings_assessable", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"max_total_outbuilding_area\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m2\", \"conditions\": [\"lot < 600 m2: 50m2\", \"600-1000 m2: 70m2\", \"> 1000-2000 m2: 80m2\", \"> 2000 m2: 150m2\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): Less than 600m2 | 600m2 - 1000m2 | Greater than 1000m2 - 2000m2 | Greater than 2000m2\nStructure scope 'Domestic outbuildings (Class 10a shed, garage, carport) (assessable)' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: E64 note: 'Except for the matters outlined in a. above, this is an alternative provision to the QDC'.\nResearcher notes: Same as RAD59 but the table header reads 'Max. GFA' rather than 'Maximum roofed area'."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_tw_e64_outbuildings_assessable@2026-09-11$q$;
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.12.3.1 RAD77$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD77 || Buildings and structures have contained within the site: - a separation from classified vegetation of 20m or the distance required to achieve a bushfire attack level (BAL) at the building, roofed structure or fire fighting water supply of no more than 29, whichever is the greater; - a separation from low threat vegetation of 10m or the distance required to achieve a bushfire attack level (BAL) at the building, roofed structure or fire fighting water supply of no more than 29, whichever is the greater; - a separation of no less than 10m between a fire fighting water supply extraction point and any classified vegetation, buildings and other roofed structures; - an area suitable for a standard fire fighting appliance to stand within 3m of a fire fighting water supply extraction point; and - an access path suitable for use by a standard fire fighting appliance having a formed width of at least 4m, a cross-fall of no greater than 5%, and a longitudinal gradient of no greater than 25%: - to, and around, each building and other roofed structure; and - to each fire fighting water supply extraction point. Note - The meaning of the terms classified vegetation and low threat vegetation as well as the method of calculating the bushfire attack level are as described in Australian Standard AS 3959.$q$, 'VERIFIED_VERBATIM', $q$rule 16256$q$, NULL, $q$6.2.12 Township zone code (6.2.12.3 Township residential precinct)$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/125/0/false/11-Sep-2026/false$q$, $q$$q$, $q$mb_tw_rad77_bushfire_separation$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_tw_rad77_bushfire_separation", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "SEPARATION.BUILDINGS", "title": "Table 6.2.12.3.1 RAD77", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SEPARATION", "operator": ">=", "value": {"op": "unencoded", "text": "RAD77 || Buildings and structures have contained within the site: - a separation from classified vegetation of 20m or the distance required to achieve a bushfire attack level (BAL) at the building, roofed structure or fire fighting water supply of no more than 29, whichever is the greater; - a separation from low threat vegetation of 10m or the distance required to achieve a bushfire attack level (BAL) at the building, roofed structure or fire fighting water supply of no more than 29, whichever is the greater; - a separation of no less than 10m between a fire fighting water supply extraction point and any classified vegetation, buildings and other roofed structures; - an area suitable for a standard fire fighting appliance to stand within 3m of a fire fighting water supply extraction point; and - an access path suitable for use by a standard fire fighting appliance having a formed width of at least 4m, a cross-fall of no greater than 5%, and a longitudinal gradient of no greater than 25%: - to, and around, each building and other roofed structure; and - to each fire fighting water supply extraction point. Note - The meaning of the terms classified vegetation and low threat vegetation as well as the method of calculating the bushfire attack level are as described in Australian Standard AS 3959.", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:TOWNSHIP/TOWNSHIP_RESIDENTIAL"}, {"level": "OVERLAY", "overlay": "CMB:OV:BUSHFIRE_HAZARD"}], "subjects": ["ANY"], "sources": [{"key": "mb_tw_rad77_bushfire_separation", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_vegetation_separation\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"classified vegetation: max(20 m, distance for BAL <= 29)\", \"low threat vegetation: max(10 m, distance for BAL <= 29)\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'Buildings and structures in bushfire hazard area' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: NO - values and constraints requirement; non-compliance makes the work assessable (limited code assessment) against the corresponding PO.\nResearcher notes: Table 1.6.1 rule 241 says Township zone land is NOT a designated bushfire prone area for the Building Regulation, but this planning RAD still applies where the Bushfire hazard overlay is mapped."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_tw_rad77_bushfire_separation@2026-09-11$q$;
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.12.3.1 RAD94$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD94 || No development is to occur within: - 50m from top of bank for W1 waterway and drainage line - 30m from top of bank for W2 waterway and drainage line - 20m from top of bank for W3 waterway and drainage line - 100m from the edge of a Ramsar wetland, 50m from all other wetlands. Note - W1, W2 and W3 waterways and drainage lines, and wetlands are mapped on Schedule 2, Section 2.5 Overlay Maps – Riparian and wetland setbacks. Note - In some cases, the top of bank may not be easily defined, as such a hydraulic measurement may be applied instead. Moreton Bay Regional Council will provide further direction on how to determine and locate the setback boundary in these locations. Note - The minimum setback distance applies to the each side of waterway.$q$, 'VERIFIED_VERBATIM', $q$rule 16278$q$, NULL, $q$6.2.12 Township zone code (6.2.12.3 Township residential precinct)$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/125/0/false/11-Sep-2026/false$q$, $q$$q$, $q$mb_tw_rad94_riparian_setbacks$q$);
