, \"formula_text\": null}\nStructure scope 'All development' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: NO - values and constraints requirement; non-compliance makes the work assessable (limited code assessment) against the corresponding PO."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_tw_rad94_riparian_setbacks@2026-09-11$q$;
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.8.1 PO1 (Part A - Criteria for assessable development; General criteria)$q$, 'PERFORMANCE_OUTCOME', $q$PO1 New buildings are not located in the Limited development zone and any other building work is only minor building work. || No example provided.$q$, 'VERIFIED_VERBATIM', $q$rule 15668$q$, NULL, $q$6.2.8 Limited development zone code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/114/0/false/11-Sep-2026/false$q$, $q$Minor building work (Schedule 1): 'An alteration, addition or extension to an existing building(s) which results in an increase in the gross floor area of the building(s) of less than five percent of the gross floor area of the existing building(s) or 50 square metres,whichever is the lesser.' No setback, site cover, height or roofed-area numbers exist anywhere in 6.2.8.$q$, $q$mb_ld_po1_no_new_buildings_minor_building_work$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_ld_po1_no_new_buildings_minor_building_work", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "OTHER", "title": "Table 6.2.8.1 PO1 (Part A - Criteria for assessable development; General criteria)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DISCRETIONARY", "provision_kind": "PERFORMANCE_OUTCOME", "measurement": "SCHEME_OTHER", "operator": "=", "value": {"op": "unencoded", "text": "PO1 New buildings are not located in the Limited development zone and any other building work is only minor building work. || No example provided.", "extracted_value": false, "extracted_operator": "="}, "unit": null, "on_noncompliance": "ASSESS_AGAINST_PERFORMANCE_OUTCOME", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "ZONE", "zone": "CMB:LIMITED_DEVELOPMENT"}], "subjects": ["ANY"], "sources": [{"key": "mb_ld_po1_no_new_buildings_minor_building_work", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"new_buildings_permitted\", \"operator\": \"=\", \"value\": false, \"unit\": null, \"conditions\": [\"new buildings: not located in the zone\", \"any other building work: only minor building work (GFA increase < 5% of existing GFA or 50 m2, whichever is the lesser)\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'All buildings, including a dwelling house, domestic outbuildings (sheds, garages, carports) and, arguably, swimming pools (as building work)' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: NO - 6.2.8 has no RADs, no 'Concurrence agency issues for building work' table and no alternative-provision notes; 6.2.8 is not listed in Table 1.6.1 (rules 245-247) or in rule 248.\nResearcher notes: The only siting-type provision in the zone code. It is a performance outcome with 'No example provided', so it is not a numeric test; it is an assessment benchmark for impact assessment (building work in the zone is always impact assessable, Table 5.7.1 rule 4428, so the whole planning scheme is the benchmark - rule 15662). A new detached shed/garage/carport is a 'new building' and is contrary to PO1; whether a swimming pool (Class 10b structure, no GFA) is a 'building' or 'other building work' under PO1 is not stated. The tool should treat Limited development zone lots as 'no accepted siting envelope - impact assessable development application required' rather than compute setbacks."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_ld_po1_no_new_buildings_minor_building_work@2026-09-11$q$;
